import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

// The real TerminalView mounts an @xterm/xterm instance imperatively and wires it to a live PTY
// (session launch, OSC status handlers, resize/jumble nudges, focus/visibility plumbing) — none of
// that has a design-time appearance of its own; the pixels come from bytes a real backend streams in.
// This preview vendors only the genuinely VISUAL shell: the banner stack + the themed terminal frame,
// with the frame's colors lifted verbatim from the real `TERM_THEME` (terminalConstants.ts) and a few
// static sample lines standing in for live PTY output.
//
// The real TerminalView also renders TerminalBanners above the terminal, omitted here (not composed)
// because its own chain nests two "AS GRAPH SOURCE" leaves (Banner, IconButton) whose vendor-
// substitution only resolves reliably as a DIRECT import, not two levels deep — the same sandbox limit
// that broke SessionTag/SevDot/ReviewStrip inside security-flow earlier this session. In the common
// idle-terminal state TerminalBanners renders nothing anyway (no critical/warning checks), so omitting
// it here costs no visible fidelity. TerminalBanners is its own separately-previewable component.
//
// The hex colors below are intentionally hardcoded, not a lint gap: they're the real xterm ITheme
// palette (terminalConstants.ts), which is deliberately independent of the app's semantic --tokens —
// a terminal emulator's palette doesn't follow the app theme.
const TERM_BG = "#181a1f";
const TERM_FG = "#eeeae4";
const TERM_DIM = "#44474f";
const TERM_ACCENT = "#c4923a";
const SAMPLE_LINES = [
  { text: "$ claude", color: TERM_FG },
  { text: "Reading project files…", color: TERM_DIM },
  { text: "✓ Ready. What would you like to work on?", color: "#5fb467" },
];

interface TerminalViewProps {
  paneId: string;
  visible?: boolean;
  focused?: boolean;
  initialCwd?: string;
  initCmd?: string;
  onCwdChange?: (path: string) => void;
  onStatusChange?: (status: "run" | "idle") => void;
  onFocus?: () => void;
}
export function TerminalView({ paneId = "pane-1", visible = true }: TerminalViewProps) {
  return (
    <Box style={{
      flex: 1, minHeight: 0, position: "relative",
      background: TERM_BG,
      display: visible ? "flex" : "none",
      flexDirection: "column",
    }}>
      <Box style={{ flex: 1, minHeight: 0, overflow: "hidden", background: TERM_BG }}>
        <Box style={{ height: "100%", padding: "6px 10px", fontFamily: '"JetBrains Mono", monospace', fontSize: 12.5, lineHeight: 1.5 }}>
          {SAMPLE_LINES.map((l, i) => (
            <Text key={i} as="div" style={{ color: l.color, whiteSpace: "pre" }}>{l.text}</Text>
          ))}
          <Text as="span" style={{ color: TERM_FG, background: TERM_ACCENT, whiteSpace: "pre" }}> </Text>
        </Box>
      </Box>
    </Box>
  );
}
